from pathlib import Path
from pypdf import PdfReader
import pdfplumber,json,hashlib
root=Path.cwd();source=root.parent/"results/V7_Maxwell_Debye_PML";out=root/"logs/v0.2.3/pdf"
target=source/"V7_global_energy_副本.pdf";original=source/"V7_global_energy.pdf"
readers={p.name:PdfReader(p) for p in [original,target]}
data={}
for name,r in readers.items():
 pages=[]
 for idx,page in enumerate(r.pages):
  annotations=[]
  for ref in page.get("/Annots",[]):
   a=ref.get_object()
   annotations.append({str(k):str(v) for k,v in a.items() if k not in ["/AP","/P"]})
  pages.append({"index1":idx+1,"label":r.page_labels[idx],"mediabox":list(page.mediabox),"text":page.extract_text(),"annotations":annotations})
 data[name]={"pages":pages,"metadata":str(r.metadata)}
 (out/(name+".txt")).write_text("\n\n".join("PAGE "+str(p["index1"])+"\n"+p["text"] for p in pages))
 print(name,len(pages),"pages",sum(len(p["annotations"]) for p in pages),"annotations")
 for p in pages:
  if p["annotations"]:print("page",p["index1"],p["annotations"])
(out/"before_inspection.json").write_text(json.dumps(data,ensure_ascii=False,indent=2)+"\n")
with pdfplumber.open(target) as pdf:
 for i,page in enumerate(pdf.pages):
  text=page.extract_text() or ""
  tags=[s for s in ["(2.4)","(2.5)","(5.2)","(5.3)","(5.4)","(5.5)","(7.1)","(7.2)","(7.3)","(7.4)","(8.1)","(8.2)","(9.2)"] if s in text]
  if tags:print("position",i+1,tags,"page bounds",page.bbox)
  words=page.extract_words()
  (out/("page_%02d_words.json"%(i+1))).write_text(json.dumps(words,ensure_ascii=False,indent=2))

